+      const measureWrapReq = (text: string, size: number, maxWidth: number) => {
+        ctx.font = `500 ${size}px "Be Vietnam Pro"`;
+        const paragraphs = text.split('\n');
+        let lines: string[] = [];
+        for (const p of paragraphs) {
+          if (!p) { lines.push(''); continue; }
+          const words = p.split(' ');
+          let currentLine = '';
+          for (const word of words) {
+            const testLine = currentLine ? currentLine + ' ' + word : word;
+            if (ctx.measureText(testLine).width <= maxWidth) { currentLine = testLine; }
+            else {
+              if (ctx.measureText(word).width > maxWidth) {
+                if (currentLine) { lines.push(currentLine); currentLine = ''; }
+                let tempLine = '';
+                for (const char of word) {
+                  if (ctx.measureText(tempLine + char).width <= maxWidth) tempLine += char;
+                  else { if (tempLine) lines.push(tempLine); tempLine = char; }
+                }
+                currentLine = tempLine;
+              } else {
+                if (currentLine) lines.push(currentLine);
+                currentLine = word;
+              }
+            }
+          }
+          if (currentLine) lines.push(currentLine);
+        }
+        return lines;
+      };
